    /// <summary>
    /// Sets or gets the record ID of the <c>Pillar</c> record for the <c>METInternalCustTable</c> table.
    /// </summary>
    /// <param name="_set">
    /// The indicator on whether to update or not.
    /// </param>
    /// <param name="_dimensionValue">
    /// The ID of the dimension value.
    /// </param>
    /// <returns>
    /// The ID of the dimension value.
    /// </returns>
    public edit METInternalPillarValue editPillarFinDimensionValue(boolean _set, DimensionValue _dimensionValue)
    {
        DimensionValue          dimensionValue = '';
        DimensionFinancialTag   dimensionFinancialTag;

        if (_set)
        {
            if (_dimensionValue == '')
            {
                this.Pillar = 0;
            }
            else
            {
                dimensionFinancialTag = DimensionFinancialTag::findByFinancialTagCategoryAndValue(DimensionAttribute::findByName(METConstants::pillar, false).financialTagCategory() , _dimensionValue);

                if (dimensionFinancialTag)
                {
                    this.Pillar = dimensionFinancialTag.RecId;
                }
                else
                {
                    this.Pillar = 0;
                }
            }
        }
        else
        {
            if (this.Pillar != 0)
            {
                dimensionValue = DimensionFinancialTag::find(this.Pillar).Value;
            }
        }
        return dimensionValue;
    }

