    /// <summary>
    /// Provides lookup for the <c>DimensionAttributeValue</c> table.
    /// </summary>
    /// <param name="_ctrl">
    /// The instance of <c>FormStringControl</c> class.
    /// </param>
    /// <param name="_dimensionName">
    /// Custom financial dimension name
    /// </param>
    public static void lookupDimensionValue(FormStringControl _ctrl, str _dimensionName)
    {
        SysTableLookup                      sysTableLookup;
        Query                               query;
        QueryBuildDataSource                qbdsDimensionFinancialTag;
        QueryBuildRange                     qbrFinancialTagCategory;

        query = new Query();
        qbdsDimensionFinancialTag = query.addDataSource(tableNum(DimensionFinancialTag));
        qbrFinancialTagCategory = qbdsDimensionFinancialTag.addRange(fieldNum(DimensionFinancialTag, FinancialTagCategory));
        qbrFinancialTagCategory.value(strFmt('%1', DimensionAttribute::findByName(_dimensionName, false).financialTagCategory()));

        sysTableLookup = sysTableLookup::newParameters(tableNum(DimensionFinancialTag), _ctrl);
        sysTableLookup.addLookupfield(fieldNum(DimensionFinancialTag, Value), true);
        sysTableLookup.addLookupfield(fieldNum(DimensionFinancialTag, Description));
        sysTableLookup.addSelectionField(fieldNum(DimensionFinancialTag, FinancialTagCategory));
        sysTableLookup.parmQuery(query);

        sysTableLookup.performFormLookup();
    }
